// Author: MiYu. Pending stage-batch consumers for real ability orders, effects, buffs and reentrant spell events.
#include "session.h"
#include "setup.h"
#include "order_ids.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=3)throw std::runtime_error("Usage: war3_spell_tests <data-root> <generated-map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession s(jass::Module::compile(jass::Program::read(archives)),info);s.attachWorld(std::move(world));s.audioMuted(true);s.configure();PlayerSetup setup(info,s.config());s.applySetup(setup);s.startMain();auto& vm=s.runtime();
        auto check=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto real=[](float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));};auto number=[](jass::Real v){return std::bit_cast<float>(v.bits());};auto code=[&](const char* id){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(id)));};auto bounds=s.world()->bounds();auto x=bounds.minX.add(bounds.maxX).divide(jass::Real::fromInteger(2)),y=bounds.minY.add(bounds.maxY).divide(jass::Real::fromInteger(2));
        vm.invoke("FogEnable",std::array{vm.boolean(false)});vm.invoke("FogMaskEnable",std::array{vm.boolean(false)});
        auto create=[&](unsigned owner,const char* type,float offset){auto u=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),code(type),vm.real(x.add(real(offset))),vm.real(y),vm.real(real(270))});vm.invoke("SetUnitPathing",std::array{u,vm.boolean(false)});return u;};
        auto caster=create(0,"Hpal",0),friendUnit=create(0,"hfoo",100),enemyUnit=create(1,"hfoo",150),undead=create(1,"ugho",200);auto c=s.units().at(caster.bits);c->maxMana=real(10000);c->mana=c->maxMana;c->healthRegen=c->manaRegen=0;auto f=s.units().at(friendUnit.bits),e=s.units().at(enemyUnit.bits);f->healthRegen=e->healthRegen=0;f->acquireRange=e->acquireRange=c->acquireRange={};s.units().at(undead.bits)->acquireRange={};s.stopUnit(friendUnit.bits);s.stopUnit(enemyUnit.bits);s.stopUnit(undead.bits);
        vm.invoke("ProbeCaster",std::array{caster});vm.invoke("ProbeRegister");auto target=[&](jass::Value u,const char* ability){vm.invoke("ProbeTarget",std::array{u,code(ability)});};auto add=[&](const char* ability){check(vm.invoke("UnitAddAbility",std::array{caster,code(ability)}).bits!=0,"Could not add source ability");};
        check(orderId("holybolt")==852092 && orderId("healingwave")==852501 && orderName(852095)=="thunderbolt","Source order registration differs");check(s.canLearnSkill(caster.bits,ObjectData::code("AHhb")),"Hero learning prerequisite rejected");check(s.learnHeroSkill(caster.bits,ObjectData::code("AHhb")) && c->skillPoints==0,"Learning did not consume skill point");
        f->life=real(100);target(friendUnit,"AHhb");auto mana=number(c->mana);check(s.targetOrder(caster.bits,friendUnit.bits,orderId("holybolt")),"Source order did not cast");s.advance(.25);check(number(f->life)<101 && std::abs(number(c->mana)-mana)<2,"Effect/cost occurred before cast point");s.advance(.5);check(number(f->life)>299 && number(c->mana)<mana-64 && s.spellCooldown(caster.bits,ObjectData::code("AHhb"))>0,"Holy light did not heal/pay/cool down");s.advance(2);check(vm.global("probe_channel").bits==1 && vm.global("probe_cast").bits==1 && vm.global("probe_effect").bits==1 && vm.global("probe_finish").bits==1 && vm.global("probe_end").bits==1,"Spell event phases differ");
        check(!s.castSpell(caster.bits,ObjectData::code("AHhb"),friendUnit.bits),"Cooldown allowed another cast");add("AHtb");target(enemyUnit,"AHtb");e->life=e->maxLife;auto life=number(e->life);check(s.castSpell(caster.bits,ObjectData::code("AHtb"),enemyUnit.bits),"Storm bolt order rejected");s.advance(1);check(number(e->life)<life-99 && e->stunned() && !s.moveUnit(enemyUnit.bits,{x,y}),"Storm bolt damage/stun not consumed");auto buff=vm.invoke("GetUnitAbilityLevel",std::array{enemyUnit,code("BPSE")});check(buff.bits==1,"Active buff not exposed as ability");vm.invoke("UnitRemoveBuffsEx",std::array{enemyUnit,vm.boolean(false),vm.boolean(true),vm.boolean(true),vm.boolean(false),vm.boolean(false),vm.boolean(false),vm.boolean(false)});check(!e->stunned(),"Magic dispel did not release stun");s.advance(2);
        add("AEer");target(enemyUnit,"AEer");check(s.castSpell(caster.bits,ObjectData::code("AEer"),enemyUnit.bits),"Roots order rejected");s.advance(1);check(e->rooted() && !s.moveUnit(enemyUnit.bits,{x,y}),"Root did not block movement");life=number(e->life);s.advance(1);check(number(e->life)<life-14,"Roots periodic damage missing");vm.invoke("UnitRemoveAbility",std::array{enemyUnit,code("BEer")});check(!e->rooted(),"Removing root buff retained movement restriction");s.advance(2);
        add("AUfn");target(enemyUnit,"AUfn");e->life=e->maxLife;check(s.castSpell(caster.bits,ObjectData::code("AUfn"),enemyUnit.bits),"Nova order rejected");s.advance(1);check(number(e->life)<number(e->maxLife)-149 && e->spellMoveFactor()<1 && e->spellAttackReduction()>0,"Nova target/area damage or frost missing");s.advance(3);
        add("AUdc");target(enemyUnit,"AUdc");e->life=e->maxLife;check(s.castSpell(caster.bits,ObjectData::code("AUdc"),enemyUnit.bits),"Death coil living target rejected");s.advance(1);check(number(e->life)<number(e->maxLife)-99,"Coil impact did not damage living enemy");s.advance(2);
        add("AOhw");target(friendUnit,"AOhw");f->life=real(100);check(s.castSpell(caster.bits,ObjectData::code("AOhw"),friendUnit.bits),"Healing wave order rejected");s.advance(1);check(number(f->life)>229,"Healing wave did not heal primary target");s.advance(2);
        add("AOcl");target(enemyUnit,"AOcl");e->life=e->maxLife;check(s.castSpell(caster.bits,ObjectData::code("AOcl"),enemyUnit.bits),"Chain lightning order rejected");s.advance(1);check(number(e->life)<number(e->maxLife)-84,"Lightning primary damage missing");s.advance(2);

        auto none=[&](const char* ability){target(vm.handle("unit",0),ability);};
        auto reset=[&]{vm.invoke("UnitResetCooldown",std::array{caster});c->mana=c->maxMana;};
        auto complete=[&]{s.advance(3);reset();};
        add("AHtc");none("AHtc");e->life=e->maxLife;auto friendLife=number(f->life);check(vm.invoke("IssueImmediateOrder",std::array{caster,vm.string("thunderclap")}).bits!=0,"Clap immediate order rejected");s.advance(1);check(number(e->life)<number(e->maxLife)-59 && e->spellMoveFactor()<1 && e->spellAttackReduction()>0 && number(f->life)>=friendLife,"Clap damage/slow/relationship missing");complete();
        add("AOws");none("AOws");e->life=e->maxLife;check(vm.invoke("IssueImmediateOrderById",std::array{caster,vm.integer(int(orderId("stomp")))}).bits!=0,"Stomp ID order rejected");s.advance(1);check(number(e->life)<number(e->maxLife)-24 && e->stunned(),"Stomp damage/stun missing");complete();
        add("AEfk");none("AEfk");e->life=e->maxLife;check(s.castSpell(caster.bits,ObjectData::code("AEfk")),"Fan immediate cast rejected");s.advance(1);check(number(e->life)<number(e->maxLife)-74,"Fan projectile damage missing");complete();
        WorldPoint aim{x.add(real(700)),y};add("AOsh");none("AOsh");e->life=e->maxLife;auto side=create(1,"hfoo",0);auto sideUnit=s.units().at(side.bits);sideUnit->y=y.add(real(600));sideUnit->acquireRange={};sideUnit->healthRegen=0;auto sideLife=number(sideUnit->life);check(vm.invoke("IssuePointOrder",std::array{caster,vm.string("shockwave"),vm.real(aim.x),vm.real(aim.y)}).bits!=0,"Wave point order rejected");s.advance(2);check(number(e->life)<number(e->maxLife)-74 && number(sideUnit->life)==sideLife,"Wave direction or damage missing");complete();
        add("AUcs");none("AUcs");e->life=e->maxLife;check(s.castSpellAt(caster.bits,ObjectData::code("AUcs"),aim),"Swarm point cast rejected");s.advance(2);check(number(e->life)<number(e->maxLife)-74,"Swarm moving damage missing");complete();
        auto summons=[&](const char* ability,bool living){std::vector<std::uint32_t> found;for(auto& [id,u]:s.units())if(u->summoner==caster.bits && u->summonAbility==ObjectData::code(ability) && (!living || number(u->life)>0))found.push_back(id);return found;};
        auto park=[&](const std::vector<std::uint32_t>& ids){for(auto id:ids){auto u=s.units().at(id);u->acquireRange={};vm.invoke("PauseUnit",std::array{vm.handle("unit",id),vm.boolean(true)});}};
        add("AHwe");none("AHwe");check(s.castSpell(caster.bits,ObjectData::code("AHwe")),"Water elemental rejected");s.advance(1);auto water=summons("AHwe",true);check(vm.global("probe_summons").bits==1 && water.size()==1 && s.units().at(water.front())->timedLife && s.units().at(water.front())->owner==0,"Water summon state missing");check(vm.invoke("IsUnitType",std::array{vm.handle("unit",water.front()),vm.handle("unittype",10)}).bits!=0,"Summoned classification missing");park(water);complete();
        add("AOsf");none("AOsf");check(s.castSpell(caster.bits,ObjectData::code("AOsf")),"Wolves rejected");s.advance(1);auto wolves=summons("AOsf",true);check(wolves.size()==2,"Source wolf count differs");park(wolves);complete();none("AOsf");check(s.castSpell(caster.bits,ObjectData::code("AOsf")),"Wolf replacement rejected");s.advance(1);auto replacement=summons("AOsf",true);check(replacement.size()==2 && std::all_of(wolves.begin(),wolves.end(),[&](auto id){return number(s.units().at(id)->life)==0;}),"Recast retained previous wolves");park(replacement);complete();
        add("AOsw");none("AOsw");WorldPoint ward{x.add(real(-200)),y};check(vm.invoke("IssuePointOrderById",std::array{caster,vm.integer(int(orderId("ward"))),vm.real(ward.x),vm.real(ward.y)}).bits!=0,"Ward point ID order rejected");s.advance(1);auto wards=summons("AOsw",true);check(wards.size()==1 && s.units().at(wards.front())->type==ObjectData::code("osp1"),"Source ward type missing");park(wards);complete();
        add("AUin");none("AUin");e->life=e->maxLife;check(s.castSpellAt(caster.bits,ObjectData::code("AUin"),{e->x,e->y}),"Inferno rejected");s.advance(.8);check(summons("AUin",true).empty(),"Inferno arrived before source impact delay");s.advance(1);auto infernals=summons("AUin",true);check(infernals.size()==1 && e->stunned() && number(e->life)<number(e->maxLife)-49,"Inferno summon/damage/stun missing");park(infernals);complete();
        WorldPoint trees{x.add(real(-400)),y};auto tree=vm.invoke("CreateDestructable",std::array{code("LTlt"),vm.real(trees.x),vm.real(trees.y),vm.real(real(0)),vm.real(real(1)),vm.integer(0)});vm.invoke("CreateDestructable",std::array{code("LTlt"),vm.real(trees.x.add(real(40))),vm.real(trees.y),vm.real(real(0)),vm.real(real(1)),vm.integer(0)});add("AEfn");none("AEfn");check(s.castSpellAt(caster.bits,ObjectData::code("AEfn"),trees),"Tree conversion rejected");s.advance(1);auto treants=summons("AEfn",true);check(!treants.empty() && s.destructables().at(tree.bits)->life==0,"Treants did not consume actual tree state");park(treants);complete();
        auto expired=vm.handle("unit",water.front());vm.invoke("UnitApplyTimedLife",std::array{expired,code("BHwe"),vm.real(real(.125f))});s.advance(.25);check(number(s.units().at(expired.bits)->life)==0,"Summon timed life did not use death lifecycle");
        s.advance(10);target(friendUnit,"AHhb");f->life=real(100);mana=number(c->mana);auto effects=vm.global("probe_effect").bits;vm.invoke("ProbeFlags",std::array{vm.boolean(true),vm.boolean(false)});check(s.castSpell(caster.bits,ObjectData::code("AHhb"),friendUnit.bits),"Interrupt setup rejected");s.advance(1);check(std::abs(number(c->mana)-mana)<2 && vm.global("probe_effect").bits==effects && !c->cast,"CAST reentrant stop did not interrupt before cost/effect");vm.invoke("ProbeFlags",std::array{vm.boolean(false),vm.boolean(true)});check(s.castSpell(caster.bits,ObjectData::code("AHhb"),friendUnit.bits),"Removal setup rejected");s.advance(1);check(!s.units().contains(caster.bits) && vm.global("probe_effect").bits==effects,"Removed caster continued its spell");
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS spell consumers: source learning/orders, unit/point/immediate effects, waves, summons/tree conversion, contexts, buffs and reentrant interruption/removal\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
